var a=80;var i=[{id:`cooking-080-01`,theoryId:80,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What is the defining order of reverse searing?`,ua:`Яка головна послідовність методу зворотного обсмажування?`},explanation:{en:`The gentle first stage targets internal doneness; the final sear creates a crust.`,ua:`Перший делікатний етап формує внутрішню готовність, а фінальний сильний жар — скоринку.`},options:[{id:`a`,text:{en:`Cook gently first, then finish with a fast hot sear`,ua:`Спершу готувати делікатно, потім швидко обсмажити на сильному жарі`}},{id:`b`,text:{en:`Sear first, then freeze raw`,ua:`Спершу обсмажити, потім заморозити сирим`}},{id:`c`,text:{en:`Boil meat until dry`,ua:`Варити м’ясо, доки воно не висохне`}}],answer:{optionIds:[`a`]}},{id:`cooking-080-02`,theoryId:80,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`Reverse searing eliminates the need to check food safety for meat.`,ua:`Зворотне обсмажування скасовує потребу перевіряти безпечність м’яса.`},explanation:{en:`Time, temperature, food type and validated endpoints still govern safety.`,ua:`Безпечність усе одно залежить від часу, температури, виду м’яса та перевірених режимів.`},answer:{value:!1}},{id:`cooking-080-03`,theoryId:80,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match each stage or tool to its function.`,ua:`Поєднайте етап чи інструмент з функцією.`},explanation:{en:`Reverse searing separates interior heating from surface browning.`,ua:`Зворотне обсмажування розділяє нагрівання середини та поверхні.`},leftItems:[{id:`l1`,text:{en:`Gentle oven stage`,ua:`Делікатне запікання`}},{id:`l2`,text:{en:`Thermometer`,ua:`Термометр`}},{id:`l3`,text:{en:`Final hot sear`,ua:`Фінальне сильне обсмажування`}}],rightItems:[{id:`r3`,text:{en:`Create brown surface crust`,ua:`Створити рум’яну скоринку`}},{id:`r2`,text:{en:`Track internal temperature`,ua:`Контроль внутрішньої температури`}},{id:`r1`,text:{en:`Gradual center heating`,ua:`Поступове нагрівання середини`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-080-04`,theoryId:80,type:`sequence`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Order a reverse-sear workflow for a thick steak.`,ua:`Упорядкуйте зворотне обсмажування товстого стейка.`},explanation:{en:`The method deliberately delays high-temperature browning.`,ua:`Метод навмисно переносить сильне підрум’янення на кінець.`},steps:[{id:`s2`,text:{en:`Remove before final target, accounting for finishing heat`,ua:`Зняти до кінцевої цілі, враховуючи фінальний нагрів`}},{id:`s1`,text:{en:`Heat gently while monitoring core temperature`,ua:`Делікатно нагрівати, контролюючи температуру середини`}},{id:`s3`,text:{en:`Sear surface quickly on a very hot pan`,ua:`Швидко обсмажити поверхню на дуже гарячій сковороді`}}],answer:{order:[`s1`,`s2`,`s3`]}},{id:`cooking-080-05`,theoryId:80,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which reverse-sear assumption is incorrect?`,ua:`Яке припущення про зворотне обсмажування хибне?`},explanation:{en:`Surface color does not establish the internal endpoint.`,ua:`Колір поверхні не підтверджує безпечну внутрішню температуру.`},options:[{id:`a`,text:{en:`Thick cuts benefit from gradual heating`,ua:`Товстим шматкам корисний поступовий нагрів`}},{id:`b`,text:{en:`The final sear can raise the center temperature further`,ua:`Фінальне обсмажування може ще нагріти середину`}},{id:`c`,text:{en:`The final crust alone proves the meat was safely cooked`,ua:`Одна фінальна скоринка доводить безпечність м’яса`}}],answer:{optionIds:[`c`]}}];var n={theoryId:80,exercises:i};export{n as default,i as exercises,a as theoryId};